/* GENERATED FILE — do not edit. Source: spec/. Run: pnpm gen */

@layer components {
  .ew-nav-rail {
    /* anatomy: root, item, label */
  }
  .ew-nav-rail { display: flex; flex-direction: column; gap: 2px; min-width: 0; margin: 0; padding: 8px; list-style: none; }
  .ew-nav-rail__item {
    display: flex; align-items: center; gap: 8px; min-width: 0; min-height: var(--ew-row-min, 40px);
    padding: 6px 8px; border-radius: var(--ew-structure-control-radius, 8px);
    color: inherit; text-decoration: none; font: inherit;
  }
  .ew-nav-rail__icon { flex: 0 0 auto; width: 1.25rem; height: 1.25rem; display: inline-grid; place-items: center; }
  .ew-nav-rail__label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1 1 auto; }
  .ew-nav-rail__group { margin: 8px 0 0; padding: 0; border: 0; min-width: 0; }
  .ew-nav-rail__group summary { cursor: pointer; font-weight: 700; padding: 6px 8px; }
  .ew-nav-rail[data-collapsed="true"] { width: 56px; }
  .ew-nav-rail[data-collapsed="true"] .ew-nav-rail__item { position: relative; justify-content: center; }
  .ew-nav-rail[data-collapsed="true"] .ew-nav-rail__label,
  .ew-nav-rail[data-collapsed="true"] .ew-nav-rail__group summary,
  .ew-nav-rail[data-collapsed="true"] .ew-badge { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  .ew-nav-rail[data-collapsed="true"] .ew-nav-rail__item:is(:hover, :focus-visible)::after {
    content: attr(data-label);
    position: absolute; left: calc(100% + 8px); top: 50%; transform: translateY(-50%); z-index: 6;
    padding: 4px 8px; border-radius: 4px; white-space: nowrap;
    background: var(--ew-color-fg-default); color: var(--ew-color-bg-page);
    font: 600 0.75rem/1.2 var(--ew-font-body, system-ui, sans-serif);
  }
  /* spec variant variant=default */
  .ew-nav-rail[data-variant="default"] { --ew-spec-variant-variant: default; }
  .ew-nav-rail:not([data-variant]) { --ew-spec-variant-variant: default; }
  .ew-nav-rail[data-size="sm"] { --ew-spec-size: sm; }
  .ew-nav-rail[data-size="md"] { --ew-spec-size: md; }
  .ew-nav-rail:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-nav-rail, .ew-nav-rail *, .ew-nav-rail *::before, .ew-nav-rail *::after {
      transition: none !important;
      animation: none !important;
    }
  }
}
